mapper.select:
        select  t.resource,t.domain,t.name,t.description,t.m_id,t.m_id mId,t.p_id,t.p_id pId,t.status_cd,t.status_cd statusCd 
from p_privilege t 
where 1 =1 

   and t.resource= #{resource}


   and t.domain= #{domain}


   and t.name= #{name}


   and t.description= #{description}


   and t.m_id= #{mId}


   and t.p_id= #{pId}


   and t.status_cd= #{statusCd}

order by t.create_time desc

   limit #{page}, #{row}

mapper.update:
        update  p_privilege t set t.status_cd = #{statusCd}

,t.b_id = #{newBId}


, t.resource= #{resource}


, t.domain= #{domain}


, t.name= #{name}


, t.description= #{description}


, t.m_id= #{mId}

 where 1=1 
and t.p_id= #{pId}

mapper.select:
        select  count(1) count 
from p_privilege t 
where 1 =1 

   and t.resource= #{resource}


   and t.domain= #{domain}


   and t.name= #{name}


   and t.description= #{description}


   and t.m_id= #{mId}


   and t.p_id= #{pId}


   and t.status_cd= #{statusCd}
